app-width:
@layer base {
.app-width { width: 90%; margin-left: auto;    margin-right: auto;  } 
}

btn:
@layer base {
.btn { color: #FFFFFF; display: inline-block; border-radius: 8px; border-style: none; font-size: 18px; cursor: pointer; transition:0.5s; background-color: #676767; background-color: #A6A6A6;  } 
@media only screen and (min-width: 992px) { .btn { font-size: 16px;  } } 
}

btn-lg:
@layer base {
.btn-lg { padding-top: 15px; padding-bottom: 15px; width: 100%;  } 
@media only screen and (min-width: 992px) { .btn-lg { padding-top: 18px; padding-bottom: 18px;  } } 
}

btn-sm:
@layer base {
.btn-sm { padding-top: 10px; padding-bottom: 10px; width: fit-content; padding-left: 15px; padding-right: 15px;  } 
}
